ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["replies_join_1"] = {
{"JOIN_REQUEST","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly|world=building",{"We've got a spare spot by the stove, I don't see why not"}},
{"JOIN_REQUEST","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly",{"More hands would help with the kids - come meet everyone"}},
{"JOIN_REQUEST","role=family_elder|tmp=seasoned|st=friendly",{"There's a spot at the fire for a decent soul - come on in"}},
{"JOIN_REQUEST","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly",{"I think the group would like you - come and meet them","I'd feel safer with another person, if you can carry your weight, yes"}},
{"JOIN_REQUEST","role=civilian_loner|tmp=seasoned|st=friendly",{"I work alone, but I've never refused good company, for a while"}},
{"JOIN_REQUEST","role=worker|tmp=seasoned|st=friendly",{"We could use another pair of hands - know any trades?"}},
{"JOIN_REQUEST","role=rescue_firefighter|tmp=seasoned|st=friendly",{"We always have room for someone willing to pull a hose"}},
{"JOIN_REQUEST","role=rescue_medical|tmp=seasoned|st=friendly",{"Can you carry? Can you keep calm in a crisis? Then we have room"}},
{"JOIN_REQUEST","role=rescue_clergy|tmp=seasoned|st=friendly",{"Join us, we turn no one away who comes in peace"}},
{"JOIN_REQUEST","role=law_deputy,law_officer|tmp=seasoned|st=friendly",{"We're always looking for good people - come to the station and talk to the sergeant"}},
{"JOIN_REQUEST","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly",{"I could deputize you, we could use someone sensible out there"}},
{"JOIN_REQUEST","role=law_trooper|tmp=veteran|st=friendly",{"Not my call - come to the checkpoint and speak to my lieutenant"}},
{"JOIN_REQUEST","role=law_corrections|tmp=seasoned|st=friendly",{"We have space in the jail, you'd be safer here than outside"}},
{"JOIN_REQUEST","role=swat_lead,swat_operator|tmp=veteran|st=friendly",{"We vet new people - come to our position and we'll see"}},
{"JOIN_REQUEST","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly",{"Can't recruit, but the sergeant might - talk to him"}},
{"JOIN_REQUEST","role=soldier_nco|tmp=veteran|st=friendly",{"We're short on hands, if you can shoot straight, I'll put in a word"}},
{"JOIN_REQUEST","role=deserter,militia|tmp=seasoned|st=friendly",{"Maybe, depends on whether I trust you with my back"}},
{"JOIN_REQUEST","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly",{"We don't take strays, prove yourself first"}},
{"JOIN_REQUEST","role=outlaw|tmp=seasoned|st=friendly",{"Another drifter, huh? Eh, fine, just split whatever you find"}},
{"JOIN_REQUEST","role=raider,raider_boss|tmp=predator|st=friendly",{"You've got a face I like, prove you'll fight and we'll see"}},
{"JOIN_REQUEST","role=gang_member,gang_boss|tmp=predator|st=friendly",{"Come to the crib, we'll see what you're about"}},
{"JOIN_REQUEST","role=biker,biker_boss|tmp=predator,veteran|st=friendly",{"A prospect, huh? You'd have to earn the patch"}},
{"JOIN_REQUEST","role=crime_member|tmp=seasoned|st=friendly",{"I'll speak to the boss - come meet him - don't embarrass me"}},
{"JOIN_REQUEST","role=prisoner|tmp=predator|st=friendly",{"We could use another guy who knows how to hold his tongue - come on"}},
{"JOIN_REQUEST","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral",{"Join us? oh God, yes, wait, no, I have to ask the others first, they're scared of strangers","Maybe? I'm- you seem decent, but it's not just me, there are kids, I can't risk it, I'm sorry","I'd love that, I really would, but we don't have the food, honestly, we have three cans and a prayer!","Oh, wow, okay, you're asking? you're ASKING me? yeah, um, yes, maybe, let me think, let me think","I don't know you -- and I want to say yes, I really do, I'm just so tired of saying no","God -- I'd say yes in a second, but I'm not the one who decides, and the one who decides is not a nice man!","We could use more hands, and I mean that, but I need to know what you can do, no offense","Hmm... hang on, that's a big question, can you give me a day? just a day?","Yeah- yeah, why not... anything beats alone, right? RIGHT? God, I'm so tired","We've got no room, it's me and my sister in a closet, I'm sorry, if we had room, we'd say yes","L-LOOK, you seem alright, but I've had my heart broken twice this week by people who seemed alright","Can you shoot? can you carry? can you stay quiet? that's all I want to know before I say yes","Can't, I'm sorry, we already lost one person we trusted, so now it's a rule, no new people, none"}},
{"JOIN_REQUEST","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral|day=0,4",{"It's only been a few days, shouldn't we wait for the soldiers? they said help was coming","Shouldn't we stay where we are? we've only just got here, I don't want to move again"}},
{"JOIN_REQUEST","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"Depends on who you are, and what you're hiding, and what you'd do for a can of beans","We could use someone, yeah, we've been short on watch, you ever stand watch?","Come meet the others... and if they don't like you, no hard feelings, if they do, you can stay","We have rules, and they're boring, and they keep us alive, you okay with that?","Not me you need to convince, it's Marge, and Marge doesn't like anyone","I'm in, personally, but I only get one vote, and I'm not the loud one","Possibly, what do you bring? I'm not asking for money, I'm asking for a skill","We've buried too many to be sloppy... so prove yourself first, then we'll talk","You can walk with us for a day, see how it goes, nobody signs anything","You've got a face I trust, and that's not nothing, and not enough, but not nothing","Another person might help us. Might be more than we can handle, too. I need to think"}},
{"JOIN_REQUEST","role=civilian_man,civilian_woman|st=friendly",{"Yes! I mean, probably yes, I mean, let me ask, but I think yes, you've been decent to us","Come on, you're already half in, the others like you, I told them about you","I was hoping you'd ask, honestly, welcome, or, I mean, almost welcome","We'd be lucky to have you, and I don't say that to just anyone"}},
{"JOIN_REQUEST","role=civilian_man,civilian_woman|st=careful",{"Not a chance","You? with us? no, absolutely not","Ask me again when I've known you longer than a minute","Why would I let a stranger near my people?","I barely trust myself, why would I trust you?"}},
{"JOIN_REQUEST","role=civilian_loner",{"Join? I work alone, I'll walk with you a bit, but that's all I promise","Only if you can keep quiet, I mean really quiet, most can't","I've had company, it ended badly, so, a day, maybe, we'll see..","Alright, but you carry your own weight, and you carry mine when I'm sick","I don't need a partner, but I could use a second pair of eyes at night, so, a trial, a short one","Sorry, I run alone, I'm slow to trust, and quick to leave","Never worked well with people, never had to, but I'm not too proud to change","You snore? you smell? you talk too much? those are my terms","I can't keep another mouth fed, even if I wanted to, which, I don't say I don't","One day, you stay close, we'll see how you do"}},
{"JOIN_REQUEST","role=civilian_loner|st=careful",{"No, nope, solo, been that way since the first week","I said no, and I meant it","Go find your own hole to crawl into","Join me? I came out here to get away from people","I've been alone since the Tuesday and I've quit being bad at it - sorry"}},
{"JOIN_REQUEST","role=family_man,family_woman",{"We've got kids, so I can't, not blind, I'd need to meet you, talk to my wife, and my mother-in-law is the hard one","Come to dinner, if you can call it that, and we'll see, my kids will decide, they're better judges than I am","No room right now, but maybe - find me tomorrow and I'll talk to them","Three kids and four adults, I'd say we have room for one more at the table, but not by much","Can you cook? can you fish? can you keep a kid quiet at three in the morning? that's the job","We'd love help, and God knows we need it, but I have to protect the kids first, you understand","My wife says no, and I say yes, so we're having a very long conversation about you, hang on","Yes, I think, I want to say yes, I'll feel better with another man around, no offense to the women"}},
{"JOIN_REQUEST","role=family_man,family_woman|st=careful",{"You want to join my family? are you out of your mind?","No, and don't come near my kids","Not near my children","I've got kids to feed, so no, I'm sorry, not today"}},
{"JOIN_REQUEST","role=family_elder",{"Honey, I'd take you in if I had a roof to offer, but I'm staying with my daughter's friends, and they decide","I could use a strong arm to carry water, yes, you can walk with me, mind my hip","Why not, I've got nothing to steal, and you look like you have manners","Ask the others, I'm just the old lady in the corner, they feed me because they feel guilty","Oh, I'd like that, I'd like company, really, I'm tired of talking to the wall"}},
{"JOIN_REQUEST","role=family_youth",{"Oh my God, yes, wait, I mean, I'd have to ask my cousin, she's in charge, I'm just the, uh, the one with the flashlight","I don't know, we're not allowed to, there's a rule, we got burned once, but you seem cool","You can hang with us a little... if you want, we're not mean, we're just careful","Cool, yeah, sure, unless you're a creep, are you a creep? you'd tell me, right?"}},
{"JOIN_REQUEST","role=worker",{"Can you work? Real work, hauling, digging, no free rides around here...","We could use a good pair of hands on the barricade, and I mean good, not just warm","Sure... you do your share and keep your nose clean, you're in, that's it, no oath, no handshake...","I'd have to ask the foreman... and the foreman is me, so, hmm, okay, give me a minute...","We vote on it, majority rules, and we haven't had a new face in a week, so you might get lucky"}},
{"JOIN_REQUEST","role=worker|st=careful",{"We don't need anybody, and we're not looking","Take it up with someone who cares -- I don't!!","We're not hiring","We're full, and I don't know you, sorry"}},
{"JOIN_REQUEST","role=rescue_medical",{"I'd welcome help, there are wounded here and I can't be everywhere, can you follow instructions?","Only if you can stand blood, and I mean a lot of it, not a paper cut","I'd say yes, but I can't promise safety, I can't promise anything, only that we try","Come, please, sit, you look worn through, and we'll see how it feels about being with us"}},
{"JOIN_REQUEST","role=rescue_medical|st=careful",{"I'm sorry, I can't, not with strangers, I have people who depend on me, and I can't take risks","No new people, I'm sorry, I can't risk bringing something in","Maybe, if you're not bitten, show me your arms first"}},
{"JOIN_REQUEST","role=rescue_clergy",{"All are welcome at our table, and I mean that, but we do have a few rules, and they're not optional","Come, brother, sister, come and sit, we'll feed you first and ask questions after","You're welcome at our table, but I do ask that anything that goes bang stays with you, wrapped","You're welcome to stay, and I will pray for you, whether you like it or not"}},
{"JOIN_REQUEST","role=rescue_clergy|st=careful",{"I'm sorry, my flock is frightened, and I can't bring in someone I don't know","Not today, forgive me","The door's open, but I'll be watching you pray"}},
{"JOIN_REQUEST","role=rescue_firefighter",{"We've got a bunk free, and a crew that's missing a few, you can carry a hose, right?","It's a firehouse, not a hotel, but yeah, if you pull your weight, there's a spot","Talk to the captain, and don't be offended if he says no, he says no to everyone","Come by the station, we'll feed you, we'll see what you're made of"}},
{"JOIN_REQUEST","role=rescue_firefighter|st=careful",{"Not now, not with the way things are!"}},
{"JOIN_REQUEST","role=militia",{"I've got a roster, six men, and I'd need to clear you with them, but come see us","We take volunteers, but only after we see what you can do with a rifle, and a night's watch","I'd say yes, but I'm not the one in charge, so you'll have to impress somebody tougher than me","Possibly, come by our post tomorrow, no weapons showing, and talk to the captain"}},
{"JOIN_REQUEST","role=militia|st=careful",{"Sorry, no, we don't take drifters","We're picky, friend, tell me where you stand"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"YES, are you kidding me? you're the best thing that's happened to us all week","You've earned it, honestly, we've been talking about you, welcome, come in","I'd trust you with my life, I've watched you do it for others, you're family!","I'll vouch for you, personally, loud, in front of everyone, you're in","Yes, and I should've asked YOU, you've done more for us than we've done for you","YES, are you kidding? we've been hoping you'd ask, you're in, you were always in","Join us? You already have, in spirit, now it's official","I'd be honored, truly honored, you've earned a place at our table","You don't have to ask, you're one of us, been one of us for a while","Yes! Heck yes, the others'll be thrilled","Of course, who better? you've done more for this place than most of us","I'd be glad of the company. Let's talk about what joining us would mean","We were just talking about asking you, funny how that works","You're the kind of person we want, kind, steady, honest","Say the word, and consider it done, no vote, no fuss","It'd be an honor, and a relief, honestly!","Absolutely, and don't let anyone give you grief about it","Nothing would make me happier, nothing, I'm serious","You'd be doing us a favor, not the other way around","I'd vouch for you in front of the whole council","You can come along anytime -- I told the others that already","Well, of course, what took you so long?","Yes, and I mean it with my whole heart","Please do, we need more people like you, much more","Stay as long as you like, leave when you want, no questions","We trust you -- and that's rare, so yes, ha","Join us, please, we could use your hands, and your heart!","The answer was always yes, you just needed to ask","You're practically family already, so, yes","It's about time you asked, welcome","I'd be proud to have you with us","Yes! oh, yes, finally, some good news","We'd be lucky, honestly lucky, to have you","You've already proved yourself ten times over, so, yes","I'd trust you with my life, so sure, join us"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=bad,worst",{"No, not you, you've got a reputation, and it's not a good one","We heard what you did, and you're not coming near us","I'd sooner share a bed with a rattlesnake!"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=careful|rep=bad,worst",{"Not a chance, get away from here"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"Join us?! Now?! I- God, I want to, I want to so bad, but what if you're one of THEM, the bad kind","Please don't take this wrong, I trust NOBODY, nobody, it's nothing about you!","Come with us? Together? I'd like that... I'd like that a lot... but I'm scared, I'm so scared","Yes- no- wait- let me think- let me ask- ugh- I can't decide, my brain won't work"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Everyone who joins eats... everyone who eats needs food, everyone who needs food costs me something...","We've lost three people this way, let in a stranger, woke up with a knife, so, forgive my caution","You'd have to earn it, first with sweat, then with blood, then with time","Maybe, but you're on probation, a week, no questions, no complaints"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"We used to be nine... now we're four... there's room... there's so much room...","Another empty chair at the table... sure... sure, why not... it'd be good to see it filled","Yes... yes, I think she would have wanted that... my wife, she was always taking in strays"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"Join us?! after what the last bunch did?! after they stole from us?! they were SO nice at first!","You better not be playing me, you better not, or I will make you regret it","FINE! You can come, but one wrong move and you're gone, hear me?"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"Oh, I'd be delighted, we'd all be delighted, come on, you'll like them","Sure you can, you've been good to us, you earned it"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Join us? Sure, we've got room for one more, what's one more mouth to feed, right? hahaha","Are you good at cards? we need a fourth for rummy... that's the only requirement"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"N-no, no, I can't, please don't ask me again","Absolutely not, and I'll thank you to leave"}},
{"JOIN_REQUEST","role=rescue_medical|st=friendly,neutral",{"We could use hands... but you'd have to scrub up, wash up, and follow every rule, no exceptions","Can you hold pressure? can you stay calm around blood? then yes, we have a place for you","If you're sick, say so now, if you're bitten, say so now, if you hide it, we'll all pay","I can use another pair of hands that don't faint - you faint?"},false,{[4]="GENERIC"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"Join us? Not a chance!!","We'd sooner take in a rattlesnake","You? With us? No way in hell","After what you did? Dream on","We don't need your kind","No way in hell, not now, not ever","Don't make me laugh","You'd turn on us in a heartbeat!!","Everyone here would run, if I said yes","You're kidding, right?","I wouldn't trust you with a spoon","No! And quit asking","Go find some other poor fools to fleece","Join? Join what? a firing squad?","The answer is no, and it'll always be no","We know who you are, and we know what you've done!","Try the next county, maybe they haven't heard","Not in a hundred years","You're not welcome within a mile of us","Never, and I hope that's clear","No, thanks, I like my throat uncut","Over my dead body","Find a rock and live under it","We have standards, and you don't meet them","I'd rather share my bed with a bear","There's a reason you're alone","Forget it, drop it, move on!","You couldn't pay me to let you in","How about you leave, and we pretend this never happened?","No... hmm, let me think... no"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"Yes! Sure! Anything! Just get us out of here!","Join? Later! First, survive!","Yes, yes, yes, whatever, just don't leave me alone with them!","Discuss it when we're safe, okay? safe first","Not now! Move! Then ask me again!","Yes! Come on, this way, hurry!"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"I'd say yes, just because you're armed, honestly","Our group could use a fighter... but, talk to the others first"}},
{"JOIN_REQUEST","role=civilian_loner|st=friendly,neutral",{"I don't sleep well with company","You snore?","You can walk behind me","I've been alone a long time"},false,false,{[1]={{t="but I can tolerate a day or two",afterMs=3500}},[2]={{t="that's a deal breaker",afterMs=3200}},[3]={{t="if you keep your mouth shut",afterMs=3500}},[4]={{t="I might've forgotten how",afterMs=3200}}}},
{"JOIN_REQUEST","role=family_elder|st=friendly,neutral",{"Why, I'd love the company, dear","I'm slow"},false,false,{[1]={{t="I can still shell peas and knit",afterMs=3500}},[2]={{t="and I snore",afterMs=3200},{t="and I tell long stories",afterMs=2800},{t="if you can stand that, you're welcome",afterMs=3000}}}},
{"JOIN_REQUEST","role=family_elder|st=careful",{"I'm too old for new friends"}},
{"JOIN_REQUEST","role=family_youth|st=friendly,neutral",{"Wait, you'd want me?","I'm not that useful"},false,false,{[1]={{t="like... me, me?",afterMs=3500},{t="okay, cool, yes, definitely",afterMs=3000}},[2]={{t="but I can carry stuff and run really fast",afterMs=3200}}}},
{"JOIN_REQUEST","role=family_youth|st=careful",{"My cousin said not to talk to strangers"}},
{"JOIN_REQUEST","role=worker|st=friendly,neutral",{"Can you work?","We're short a man for the night shift","Join the crew?"},false,false,{[1]={{t="I mean really work, haul, dig, patch",afterMs=3500},{t="then yes",afterMs=3000}},[2]={{t="you interested?",afterMs=3200}},[3]={{t="talk to the foreman, and don't be offended if he grunts",afterMs=3500}}}},
{"JOIN_REQUEST","role=family_man,family_woman|st=friendly,neutral",{"Tell me about yourself first","We have a spare mattress","I'd like to say yes"},false,false,{[1]={{t="I have to ask, for the children",afterMs=3500}},[2]={{t="and a pot of soup",afterMs=3200},{t="that's all I can offer",afterMs=2800}},[3]={{t="but my wife has the final word",afterMs=3500},{t="and she's careful",afterMs=3000}}}},
{"JOIN_REQUEST","role=rescue_clergy|st=friendly,neutral",{"All are welcome at the table","Come, stay, I'll find you a pew and a blanket"},false,false,{[1]={{t="the only requirement is a kind heart",afterMs=3500}},[2]={{t="you can decide later",afterMs=3200}}}},
{"JOIN_REQUEST","role=rescue_firefighter|st=friendly,neutral",{"We take volunteers..","Talk to the chief"},false,false,{[1]={{t="can you haul hose? can you stay calm?",afterMs=3500}},[2]={{t="he's gruff, but he's fair",afterMs=3200}}}},
{"JOIN_REQUEST","role=militia|st=friendly,neutral",{"You'd have to stand a watch before we vote...","We take decent folks, and turn away the rest"},false,false,{[1]={{t="that's fair, right?",afterMs=3500}}}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|st=careful",{"Absolutely not","Join us?","We don't take strangers","I can't","I don't know you, so no, maybe later, maybe never","Not today, not with strangers, sorry","I need more time, a lot more time"},false,false,{[2]={{t="You?",afterMs=3000},{t="That's funny",afterMs=2800}},[3]={{t="that's how it is",afterMs=3000}},[4]={{t="my people wouldn't allow it",afterMs=3000}}}},
{"JOIN_REQUEST","reg=raider|st=neutral,careful",{"You want in? Doing what, exactly? I don't take passengers","Join us? Prove you're worth feeding first, and no, talking doesn't count","Everyone who ever asked to join was after something, so what's yours?","We're full, and I don't trust new faces, come back when you've got something to offer","You can carry stuff, dig holes, and shut up, think you can handle that?","Last guy who joined us tried to rob us, so forgive me if I'm picky","Why not, another gun's another gun - cross me and you're on your own","I got a job that needs doing, you do it right, we talk about joining"},false,{[5]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=raider|st=hostile",{"Join us? You'd be lucky if I let you walk away!","You want in my crew? You wanna die faster, there are easier ways!"}},
{"JOIN_REQUEST","reg=raider|st=friendly",{"Honestly? I could use the help, it's been me and two guys and they're driving me crazy, you any good with a gun?","I'd love the company, {g:man|lady}, but the boss decides - I'll ask him, wait here"},false,{[1]="JOIN_GROUP"}},
{"JOIN_REQUEST","role=raider_boss,gang_boss,biker_boss|st=neutral,careful",{"My crew is not a charity, you'll earn your spot or you'll leave without one"}},
{"JOIN_REQUEST","reg=gang|st=neutral,careful",{"Join the set? That's not how it works, you gotta be vouched for","You think you can just walk in and be one of us? Nah, you gotta earn it","We take care of our own, and you ain't one of ours, yet","Prove yourself, then we talk, simple as that","Man, we lost three last week, we're not turning anyone away, you willing to fight?"},false,{[5]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=gang|st=hostile",{"Join us? Nobody joins, they get jumped in, and you don't look like you can take it"}},
{"JOIN_REQUEST","reg=gang|st=friendly",{"Aight, you can ride with us a while, no promises, but we'll see how it goes"},false,{[1]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=club|st=neutral,careful",{"This ain't a social club, {g:brother|sister}, we've got rules, and prospects do the dirty work","We don't take strangers, but we take recommendations","You'd have to be sponsored by a patch, and I don't see one","Ride along for a day, we'll see what you're made of","Club's been hit hard, we could use another set of hands, but don't mistake that for trust","This isn't how you earn a patch, friend"},false,{[4]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=club|st=hostile",{"Join us? You'd better have a good reason, or a good funeral plan"}},
{"JOIN_REQUEST","reg=club|st=friendly",{"I like your attitude, {g:brother|sister}, come on, but you pull your weight"},false,{[1]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=crime|st=neutral,careful",{"We are always looking for capable individuals, are you capable?","Joining requires a reference, do you have one?","An interesting proposition, what do you bring to the table?","Our organization has standards, I'd need to see them met"}},
{"JOIN_REQUEST","reg=crime|st=hostile",{"I do not recruit those who threaten me"}},
{"JOIN_REQUEST","reg=crime|st=friendly",{"Let's discuss it, over a drink, if I can find one"},false,{[1]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=prison|st=neutral,careful",{"Join us? You'd regret it, we're not good company","I-- I don't know, I don't trust people, but maybe, I guess, depends what you want","There's six of us, we don't need a seventh, no offense","Why? What do you get out of it?"}},
{"JOIN_REQUEST","reg=prison|st=hostile",{"No! No, get away, I won't take anyone else!"}},
{"JOIN_REQUEST","reg=prison|st=friendly",{"Honestly? I'd love the company, so long as you're not planning anything"},false,{[1]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=outlaw|st=neutral,careful",{"I travel alone, it's safer","Join me? For what? I'm barely holding on myself","Two can move quieter than three, and three's a crowd, so no","You can tag along, but if you slow me down, I'm leaving you behind"},false,{[4]="JOIN_GROUP"}},
{"JOIN_REQUEST","reg=outlaw|st=friendly",{"Alright, come with me, but keep your mouth shut and your eyes open"},false,{[1]="JOIN_GROUP"}},
{"JOIN_REQUEST","role=deserter|st=neutral,careful",{"I can't take anyone, I'm barely hiding myself"}},
{"JOIN_REQUEST","reg=law|st=neutral,careful",{"I can't deputize you, but I can take you to the courthouse","We aren't taking volunteers at the moment","Come with us to the courthouse, we'll find a place for you","You'd have to be vetted by the sheriff, and he's busy","Any able-bodied person is welcome to help, but you'll follow orders","A badge doesn't make this a recruiting office"},false,{[5]="JOIN_GROUP"}},
